import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"2026-09-05 上线检查记录","description":"","frontmatter":{},"headers":[],"relativePath":"operations/verification.md","filePath":"operations/verification.md","lastUpdated":0}`),a={name:`operations/verification.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="_2026-09-05-上线检查记录" tabindex="-1">2026-09-05 上线检查记录 <a class="header-anchor" href="#_2026-09-05-上线检查记录" aria-label="Permalink to “2026-09-05 上线检查记录”">​</a></h1><p>本页记录本次正式升级的检查范围。检查采用生产只读验证与升级前隔离环境写操作测试相结合，避免在正式用户数据中创建订单、发送外部邮件或执行删除。</p><h2 id="正式系统结果" tabindex="-1">正式系统结果 <a class="header-anchor" href="#正式系统结果" aria-label="Permalink to “正式系统结果”">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>结果</th></tr></thead><tbody><tr><td>公共页面与公共接口</td><td>18/18 通过</td></tr><tr><td>已登录用户只读接口</td><td>43/43 通过</td></tr><tr><td>管理员只读接口</td><td>18/18 通过</td></tr><tr><td>数据库关联完整性</td><td>无孤立邮箱、无孤立邮件、无重复 IMAP UID</td></tr><tr><td>PostgreSQL 迁移</td><td>已执行到 047</td></tr><tr><td>Redis</td><td><code>PONG</code></td></tr><tr><td>rspamd</td><td>配置语法检查通过</td></tr><tr><td>Nginx</td><td>配置检查通过</td></tr><tr><td>后端近期致命错误</td><td>未发现 fatal、panic 或迁移错误</td></tr><tr><td>SMTP</td><td>25、587 服务响应正常</td></tr><tr><td>IMAPS / POP3S</td><td>993、995 TLS 连接正常</td></tr><tr><td>DNS</td><td>MX、SPF、DKIM、DMARC 记录可读取</td></tr><tr><td>品牌静态资源</td><td>草丛 Mail Logo 响应正常，类型和权限正确</td></tr></tbody></table><h2 id="数据保留" tabindex="-1">数据保留 <a class="header-anchor" href="#数据保留" aria-label="Permalink to “数据保留”">​</a></h2><p>原系统的 166 个用户、182 个邮箱和 777 封邮件在升级后保留。检查时数据库中没有发现邮箱或邮件的孤立外键，也没有发现重复 UID。</p><p>这些数字是本次升级时的快照，不是实时运行状态。后续新增用户和邮件会自然改变统计值。</p><h2 id="tls-修复" tabindex="-1">TLS 修复 <a class="header-anchor" href="#tls-修复" aria-label="Permalink to “TLS 修复”">​</a></h2><p>检查发现旧邮件协议证书已经过期，且原网页证书不包含邮件主机名。现已为 <code>mail.to9.us</code> 签发并部署独立证书，验证 SMTP STARTTLS、IMAPS 和 POP3S 均提供主机名匹配的新证书，并配置续期后的自动加载。</p><h2 id="隔离环境验证" tabindex="-1">隔离环境验证 <a class="header-anchor" href="#隔离环境验证" aria-label="Permalink to “隔离环境验证”">​</a></h2><p>升级前使用恢复的数据副本完成后端测试、前端与官网构建、数据库迁移、注册流程以及用户和管理员接口验证。隔离测试容器、数据库、镜像和临时文件在正式上线后已清理。</p><h2 id="范围说明" tabindex="-1">范围说明 <a class="header-anchor" href="#范围说明" aria-label="Permalink to “范围说明”">​</a></h2><p>正式环境没有为了检查而执行真实付款、外部批量发信、永久删除、重置用户安全设置等有副作用操作。相关代码路径和接口已在隔离环境测试；支付供应商、外部收件服务器及通知平台仍属于第三方依赖，需要持续监控实际回调和投递结果。</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};